import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;
import javafx.application.Application;

/**
 * A simple predator-prey simulator, based on a rectangular field.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public class Simulator
{
    @FunctionalInterface
    private interface ActorFactory
    {
        Actor create(Field field, Location location);
    }

    private static final class SpawnRule
    {
        private final double creationProbability;
        private final ActorFactory factory;

        private SpawnRule(double creationProbability, ActorFactory factory)
        {
            this.creationProbability = creationProbability;
            this.factory = factory;
        }
    }

    // Constants representing configuration information for the simulation:
    //   The default width for the grid:
    private static final int DEFAULT_WIDTH = 120;
    //   The default height for the grid:
    private static final int DEFAULT_DEPTH = 160;

    // Constants representing the creation probabilities for the actors:
    //   Primary consumers:
    private static final double GRASSHOPPER_CREATION_PROBABILITY   = 0.15;
    private static final double HARVESTER_ANT_CREATION_PROBABILITY = 0.25;
    private static final double TERMITE_CREATION_PROBABILITY       = 0.21;
    private static final double IMPALA_CREATION_PROBABILITY        = 0.15;
    //   Secondary consumers:
    private static final double PANGOLIN_CREATION_PROBABILITY      = 0.125;
    private static final double AARDVARK_CREATION_PROBABILITY      = 0.12;
    private static final double MONGOOSE_CREATION_PROBABILITY      = 0.12;
    //   Producers:
    private static final double STAR_GRASS_CREATION_PROBABILITY    = 0.05;
    private static final double RED_OAT_GRASS_CREATION_PROBABILITY = 0.04;
    private static final double ACACIA_CREATION_PROBABILITY        = 0.04;

    // Constants representing the color of each actor in the simulation view:
    //   Primary consumers:
    private static final Color GRASSHOPPER_COLOR   = new Color(188, 248, 236);
    private static final Color HARVESTER_ANT_COLOR = new Color(4, 139, 168);
    private static final Color TERMITE_COLOR       = new Color(22, 219, 147);
    private static final Color IMPALA_COLOR        = new Color(239, 234, 90);
    //   Secondary consumers:
    private static final Color PANGOLIN_COLOR      = new Color(242, 158, 76);
    private static final Color AARDVARK_COLOR      = new Color(204, 183, 174);
    private static final Color MONGOOSE_COLOR      = new Color(65, 69, 53);
    //   Producers:
    private static final Color STAR_GRASS_COLOR    = new Color(125, 97, 103);
    private static final Color RED_OAT_GRASS_COLOR = new Color(164, 3, 111);
    private static final Color ACACIA_COLOR        = new Color(187, 214, 134);
    // Carcasses of consumers
    private static final Color CARCASS_COLOR       = new Color(202,0,0);

    // The ordered species creation rules for a starting field.
    private static final List<SpawnRule> INITIAL_POPULATION_RULES = List.of(
        new SpawnRule(GRASSHOPPER_CREATION_PROBABILITY, (field, location) -> new Grasshopper(true, field, location)),
        new SpawnRule(HARVESTER_ANT_CREATION_PROBABILITY, (field, location) -> new HarvesterAnt(true, field, location)),
        new SpawnRule(TERMITE_CREATION_PROBABILITY, (field, location) -> new Termite(true, field, location)),
        new SpawnRule(IMPALA_CREATION_PROBABILITY, (field, location) -> new Impala(true, field, location)),
        new SpawnRule(PANGOLIN_CREATION_PROBABILITY, (field, location) -> new Pangolin(true, field, location)),
        new SpawnRule(AARDVARK_CREATION_PROBABILITY, (field, location) -> new Aardvark(true, field, location)),
        new SpawnRule(MONGOOSE_CREATION_PROBABILITY, (field, location) -> new Mongoose(true, field, location)),
        new SpawnRule(STAR_GRASS_CREATION_PROBABILITY, StarGrass::new),
        new SpawnRule(RED_OAT_GRASS_CREATION_PROBABILITY, RedOatGrass::new),
        new SpawnRule(ACACIA_CREATION_PROBABILITY, Acacia::new)
    );

    // The number of steps in a day:
    public static final int NUMBER_OF_STEPS_PER_DAY = 25;

    // List of actors in the field:
    private List<Actor> actors;
    // The current state of the field:
    private static Field field;
    // The current step of the simulation.
    private static int step = 0;
    // Statistics for the current field state.
    private static FieldStats stats;
    // A graphical view of the simulation:
    private static SimulatorView view;
    // A Boolean indicating whether or not to reset the StatisticsView:
    public static boolean resetStatisticsView = false;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * 
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        boolean isSizeImpossible = depth <= 0 || width <= 0;

        if (isSizeImpossible)
        {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");

            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        actors = new ArrayList<>();
        field = new Field(depth, width);
        stats = new FieldStats();
        resetSimulationSystems();

        // Create a view of the state of each location in the field:
        view = new SimulatorView(this, stats, depth, width);
        registerViewColors();

        // Show the statistics window:
        new Thread(() -> {
            Application.launch(StatisticsView.class);
        }).start();

        // Setup a valid starting point:
        reset();
    }

    /**
     * @return The current step in the simulation.
     */
    public static int getCurrentStep() { return step; }

    /**
     * @return The current field in the simulation.
     */
    public static Field getCurrentField() { return field; }

    /**
     * @return The field statistics collector used by the simulation views.
     */
    public static FieldStats getFieldStats() { return stats; }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (4000 steps).
     */
    public void runLongSimulation()
    {
        simulate(4000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * 
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for (int step = 1; step <= numSteps && view.isViable(field); step++)
        {
            simulateOneStep();
            //delay(60);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each actor.
     */
    public void simulateOneStep()
    {
        step++;

        // Update the weather:
        if (TimeSystem.hasDayChanged())
        {
            WeatherSystem.changeToNextDay();

        }

        // Provide space for newborn actors:
        List<Actor> newActors = new ArrayList<>();

        // Let all actors act:
        for (Iterator<Actor> it = actors.iterator(); it.hasNext(); )
        {
            Actor actor = it.next();

            actor.act(newActors);

            if(!actor.getIsAlive()) it.remove();
        }

        // Add the newly born actors to the main list:
        actors.addAll(newActors);

        view.showStatus(step, field);
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        actors.clear();
        resetSimulationSystems();
        populate();

        // Show the starting state in the view:
        view.showStatus(step, field);

        // Toggle boolean to show StatisticsView should be reset:
        resetStatisticsView = true;
    }

    /**
     * Reset shared simulation support systems for a fresh run.
     */
    private void resetSimulationSystems()
    {
        TimeSystem.reset();
        WeatherSystem.reset();
    }

    /**
     * Randomly populate the field with actors.
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();

        for (int row = 0; row < field.getDepth(); row++)
        {
            for (int col = 0; col < field.getWidth(); col++)
            {
                Location location = new Location(row, col);
                Actor actor = createInitialActor(location, rand);

                if (actor != null) actors.add(actor);

import javafx.application.Application;
import javafx.stage.Stage;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.layout.BorderPane;
import javafx.scene.control.Label;
import javafx.scene.chart.LineChart;
import javafx.scene.chart.NumberAxis;
import javafx.geometry.Insets;
import javafx.animation.Timeline;
import javafx.animation.KeyFrame;
import javafx.util.Duration;
import javafx.scene.chart.XYChart;
import javafx.scene.chart.XYChart.Series;
import javafx.scene.chart.XYChart.Data;
import java.util.HashMap;
import java.util.Map;

/**
 * A graphical view of the population of each species over time as the
 * simulation runs its courses.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public class StatisticsView extends Application
{
    // Constants representing the JavaFX window properties:
    //   The default size of the window:
    private static final int WINDOW_WIDTH = 800;
    private static final int WINDOW_HEIGHT = 600;
    //   The default title of the window:
    private static final String WINDOW_TITLE = "Statistics";

    // Constants representing JavaFX GUI components:
    //   The root layout component:
    private static BorderPane root;
    //   An informational label explaining the window:
    private static Label infoLabel;
    //   The line chart showing populations:
    private static LineChart<Number, Number> lineChart;
    //   The axes of the population line chart:
    private static NumberAxis xAxis, yAxis;
    //   The XYSeries representing each population over time:
    private static final Map<Class<? extends Actor>, Series<Number, Number>> actorXYSeries = new HashMap<>();

    // The time between updates for the stats:
    private static final double UPDATE_TIME_IN_SECONDS = 0.1;
    // The last day recorded:
    private static int lastDayRecorded = -1; // Set to -1 so we record day 0
    // The highest recorded population:
    private static int highestPopulation = 0;

    /**
     * @param stage The stage (window) for JavaFX.
     */
    @Override
    public void start(Stage stage)
    {
        // Create the root layout component:
        root = new BorderPane();

        // Create the scene:
        Scene scene = new Scene(root, WINDOW_WIDTH, WINDOW_HEIGHT);

        // Create the informational label:
        infoLabel = new Label("The chart below shows the population of each species over time:");

        // Create the line chart:
        lineChart = getPopulationLineChart();
        lineChart.setAnimated(false);

        // Set the initial properties of the root BorderPane:
        final int ROOT_PADDING = 5;
        root.setTop(infoLabel);
        root.setCenter(lineChart);
        root.setPadding(new Insets(ROOT_PADDING, ROOT_PADDING, ROOT_PADDING, ROOT_PADDING));

        // Set the initial properties of the stage and show it:
        stage.setScene(scene);
        stage.setTitle(WINDOW_TITLE);
        stage.show();

        // Create a timeline to update the population line chart at a fixed rate:
        KeyFrame keyFrame = new KeyFrame(Duration.millis(UPDATE_TIME_IN_SECONDS * 1000), e -> updatePopulationLineChart());
        Timeline timeline = new Timeline(keyFrame);
        timeline.setCycleCount(Timeline.INDEFINITE);
        timeline.play();
    }

    /**
     * Create a line chart for the population.
     * 
     * @return A line chart representing population.
     */
    private static LineChart<Number, Number> getPopulationLineChart()
    {
        // Create the axes:
        final int xAxisStep = 5;
        final int yAxisStep = 1000;
        xAxis = new NumberAxis(0, 0, xAxisStep);
        yAxis = new NumberAxis(0, 0, yAxisStep);
        xAxis.setLabel("Days");
        yAxis.setLabel("Population");

        // Create the line chart itself:
        return new LineChart<>(xAxis, yAxis);
    }

    /**
     * Update the data for the population line chart. This is called
     * periodically.
     */
    private void updatePopulationLineChart()
    {
        // Reset if necessary:
        if (Simulator.resetStatisticsView)
        {
            resetPopulationLineChart();
            Simulator.resetStatisticsView = false;
        }

        // Guard statement: Don't continue with this if the day
        // hasn't changed since the last update:
        if (lastDayRecorded == TimeSystem.getCurrentDay()) return;

        // Iterate through each counter in FieldStats:
        Field field = Simulator.getCurrentField();
        Map<Class<? extends Actor>, Counter> counters = Simulator.getFieldStats().getCounters(field);

        for (Map.Entry<Class<? extends Actor>, Counter> entry : counters.entrySet())
        {
            Class<? extends Actor> actorType = entry.getKey();
            Counter counter = entry.getValue();

            // Get the new data to add to the XYSeries:
            Data<Number, Number> newData = new XYChart.Data<>(TimeSystem.getCurrentDay(), counter.getCount());

            // Create a new XYSeries for this actor if there is none already:
            if (!actorXYSeries.containsKey(actorType))
            {
                Series<Number, Number> series = new XYChart.Series<>();
                series.setName(counter.getName());

                lineChart.getData().add(series);

                actorXYSeries.put(actorType, series);
            }

            // Update the XYSeries for this Actor:
            Series<Number, Number> series = actorXYSeries.get(actorType);
            series.getData().add(newData); 

            // Update the highest population if necessary:
            if (counter.getCount() > highestPopulation) highestPopulation = counter.getCount();
        }

        // Set the new last day recorded:
        lastDayRecorded = TimeSystem.getCurrentDay();

        // Set the upper bounds for each of the axes:
        xAxis.setUpperBound(TimeSystem.getCurrentDay());
        yAxis.setUpperBound(highestPopulation);
    }

    /**
     * Reset the population line chart.
     */
    public static void resetPopulationLineChart()
    {
        lineChart = getPopulationLineChart();
        root.setCenter(lineChart);

        lineChart.getData().clear();

        actorXYSeries.clear();

        lastDayRecorded = -1;

        highestPopulation = 0;
    }
}

