110	    /**
111	     * Update the data for the population line chart. This is called
112	     * periodically.
113	     */
114	    private void updatePopulationLineChart()
115	    {
116	        int currentStep = Simulator.getCurrentStep();
117	        int currentDay = TimeSystem.getCurrentDay();
118	
119	        if (hasSimulationReset(currentStep))
120	        {
121	            resetPopulationLineChart();
122	        }
123	        
124	        // Guard statement: Don't continue with this if the day
125	        // hasn't changed since the last update:
126	        if (lastDayRecorded == currentDay) return;
127	        
128	        // Iterate through each counter in FieldStats:
129	        Field field = Simulator.getCurrentField();
130	        Map<Class<? extends Actor>, Counter> counters = Simulator.getFieldStats().getCounters(field);
131	        
132	        for (Map.Entry<Class<? extends Actor>, Counter> entry : counters.entrySet())
133	        {
134	            Class<? extends Actor> actorType = entry.getKey();
135	            Counter counter = entry.getValue();
136	            
137	            // Get the new data to add to the XYSeries:
138	            Data<Number, Number> newData = new XYChart.Data<>(currentDay, counter.getCount());
139	            
140	            // Create a new XYSeries for this actor if there is none already:
141	            if (!actorXYSeries.containsKey(actorType))
142	            {
143	                Series<Number, Number> series = new XYChart.Series<>();
144	                series.setName(counter.getName());
145	                
146	                lineChart.getData().add(series);
147	                
148	                actorXYSeries.put(actorType, series);
149	            }
150	            
151	            // Update the XYSeries for this Actor:
152	            Series<Number, Number> series = actorXYSeries.get(actorType);
153	            series.getData().add(newData); 
154	            
155	            // Update the highest population if necessary:
156	            if (counter.getCount() > highestPopulation) highestPopulation = counter.getCount();
157	        }
158	        
159	        // Set the new last day recorded:
160	        lastDayRecorded = currentDay;
161	        lastStepRecorded = currentStep;
162	        
163	        // Set the upper bounds for each of the axes:
164	        xAxis.setUpperBound(currentDay);
165	        yAxis.setUpperBound(highestPopulation);
166	    }
